"""Verify the real Git-tag version providers in an isolated repository."""

import shutil
import subprocess
import sys
from email.parser import Parser
from pathlib import Path

import pytest


def run(root: Path, *args: str) -> str:
    return subprocess.run(
        args, cwd=root, check=True, capture_output=True, text=True
    ).stdout.strip()


def package_version(root: Path, output: Path) -> str:
    # Metadata is generated by the configured setuptools backend, not a mock.
    output.mkdir()
    name = run(
        root,
        sys.executable,
        "-c",
        "from setuptools.build_meta import prepare_metadata_for_build_wheel; "
        "print(prepare_metadata_for_build_wheel(" + repr(str(output)) + "))",
    ).splitlines()[-1]
    metadata = Parser().parsestr((output / name / "METADATA").read_text("utf-8"))
    version = metadata["Version"]
    assert version is not None
    return str(version)


@pytest.mark.portable
def test_git_versions_and_pre_one_breaking_bump(tmp_path: Path) -> None:
    repo = tmp_path / "repo"
    repo.mkdir()
    source = Path(__file__).resolve().parents[2]
    shutil.copy2(source / "pyproject.toml", repo)
    shutil.copytree(
        source / "src",
        repo / "src",
        ignore=shutil.ignore_patterns("__pycache__", "*.egg-info"),
    )
    run(repo, "git", "init")
    run(repo, "git", "config", "user.name", "Version Test")
    run(repo, "git", "config", "user.email", "test@example.invalid")
    run(repo, "git", "config", "commit.gpgsign", "false")
    run(repo, "git", "add", ".")
    run(repo, "git", "commit", "-m", "feat: initial package")
    assert ".dev" in package_version(repo, tmp_path / "untagged")
    run(repo, "git", "tag", "v0.2.0")
    assert package_version(repo, tmp_path / "tagged") == "0.2.0"

    run(
        repo,
        "git",
        "commit",
        "--allow-empty",
        "-m",
        "feat!: change interface",
        "-m",
        "BREAKING CHANGE: test-only change",
    )
    proposed = run(repo, sys.executable, "-m", "commitizen", "bump", "--get-next")
    assert proposed == "0.3.0"
    development = package_version(repo, tmp_path / "development")
    assert development.startswith("0.2.1.dev")
    assert development != proposed
    assert run(repo, "git", "tag", "--list") == "v0.2.0"


@pytest.mark.portable
def test_commitizen_rejects_nonconventional_message() -> None:
    root = Path(__file__).resolve().parents[2]
    cmd = [sys.executable, "-m", "commitizen", "check", "--message"]
    assert subprocess.run([*cmd, "fix: correct behavior"], cwd=root).returncode == 0
    assert subprocess.run([*cmd, "random message"], cwd=root).returncode != 0
